"""docs/roadmap/README.md is generated by scripts/roadmap_index.py and must stay fresh."""

from __future__ import annotations

from pathlib import Path

import pytest
import roadmap_index

ROOT = Path(__file__).parents[2]


def test_committed_roadmap_index_is_fresh() -> None:
    committed = (ROOT / roadmap_index.INDEX).read_text(encoding="utf-8")
    assert committed == roadmap_index.render(ROOT), (
        "docs/roadmap/README.md is stale; run: uv run python scripts/roadmap_index.py"
    )


def test_check_mode_passes_on_the_committed_tree() -> None:
    assert roadmap_index.main(["--check"]) == 0


def _tree(tmp_path: Path, files: dict[str, str]) -> Path:
    for rel, text in files.items():
        target = tmp_path / rel
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding="utf-8")
    return tmp_path


_BACKLOG = "# Idea\n\n**Status:** Idea\n**Rough size:** M\n"
_REFACTOR = "# Split\n\n**Risk:** H\n"


def test_render_lists_each_family(tmp_path: Path) -> None:
    root = _tree(
        tmp_path,
        {
            "docs/roadmap/backlog/idea.md": _BACKLOG,
            "docs/roadmap/refactors/split.md": _REFACTOR,
        },
    )
    text = roadmap_index.render(root)
    assert "| [Idea](backlog/idea.md) | Idea | M |" in text
    assert "| [Split](refactors/split.md) | H |" in text
    assert "[STATUS.md](../../STATUS.md)" in text
    assert "docs/work" not in text and "wip-limit" not in text


@pytest.mark.parametrize(
    ("rel", "text", "message"),
    [
        ("docs/roadmap/backlog/x.md", "# X\n\n**Status:** Maybe\n**Rough size:** M\n", "Status"),
        ("docs/roadmap/refactors/x.md", "# X\n\n**Risk:** extreme\n", "Risk"),
    ],
)
def test_render_rejects_template_violations(
    tmp_path: Path, rel: str, text: str, message: str
) -> None:
    root = _tree(
        tmp_path,
        {
            "docs/roadmap/backlog/ok.md": _BACKLOG,
            "docs/roadmap/refactors/ok.md": _REFACTOR,
            rel: text,
        },
    )
    with pytest.raises(roadmap_index.RoadmapError, match=message):
        roadmap_index.render(root)
